namespace RecipeCommunity.Models;

public class Recipe
{
    public int Id { get; set; }
    public string Title { get; set; } = string.Empty;
    public string Category { get; set; } = string.Empty;
    public string Ingredients { get; set; } = string.Empty;
    public string Steps { get; set; } = string.Empty;
    public double AverageRating { get; set; }
    public int RatingCount { get; set; }
}

public static class RecipeData
{
    public static List<Recipe> Recipes { get; } = new()
    {
        new Recipe
        {
            Id = 1, Title = "Classic Pancakes", Category = "Breakfast",
            Ingredients = "2 cups flour\n2 eggs\n1.5 cups milk\n2 tbsp sugar\n1 tsp baking powder\nPinch of salt",
            Steps = "1. Mix dry ingredients.\n2. Whisk eggs and milk together.\n3. Combine wet and dry ingredients.\n4. Cook on a greased griddle until golden on each side.",
            AverageRating = 4.5, RatingCount = 12
        },
        new Recipe
        {
            Id = 2, Title = "Avocado Toast", Category = "Breakfast",
            Ingredients = "2 slices sourdough bread\n1 ripe avocado\nSalt and pepper\nRed pepper flakes\nLemon juice",
            Steps = "1. Toast the bread until golden.\n2. Mash the avocado with lemon juice, salt, and pepper.\n3. Spread on toast and sprinkle with red pepper flakes.",
            AverageRating = 4.2, RatingCount = 8
        },
        new Recipe
        {
            Id = 3, Title = "Spaghetti Carbonara", Category = "Dinner",
            Ingredients = "400g spaghetti\n200g pancetta\n4 egg yolks\n100g Pecorino Romano\nBlack pepper",
            Steps = "1. Cook pasta in salted water.\n2. Fry pancetta until crisp.\n3. Mix egg yolks with grated cheese.\n4. Toss hot pasta with pancetta, then stir in egg mixture off heat.\n5. Season with pepper and serve.",
            AverageRating = 4.8, RatingCount = 20
        },
        new Recipe
        {
            Id = 4, Title = "Chicken Stir-Fry", Category = "Dinner",
            Ingredients = "500g chicken breast\n2 bell peppers\n1 broccoli head\n3 tbsp soy sauce\n1 tbsp sesame oil\n2 cloves garlic\nGinger",
            Steps = "1. Slice chicken and vegetables.\n2. Stir-fry chicken in hot oil until cooked.\n3. Add vegetables, garlic, and ginger.\n4. Add soy sauce and sesame oil.\n5. Serve over rice.",
            AverageRating = 4.3, RatingCount = 15
        },
        new Recipe
        {
            Id = 5, Title = "Chocolate Chip Cookies", Category = "Desserts",
            Ingredients = "2.25 cups flour\n1 cup butter\n0.75 cup sugar\n0.75 cup brown sugar\n2 eggs\n1 tsp vanilla\n1 tsp baking soda\n2 cups chocolate chips",
            Steps = "1. Cream butter and sugars.\n2. Beat in eggs and vanilla.\n3. Mix in flour and baking soda.\n4. Fold in chocolate chips.\n5. Bake at 375°F for 9-11 minutes.",
            AverageRating = 4.9, RatingCount = 30
        },
        new Recipe
        {
            Id = 6, Title = "Tiramisu", Category = "Desserts",
            Ingredients = "6 egg yolks\n0.75 cup sugar\n500g mascarpone\n2 cups heavy cream\n2 cups espresso\nLadyfinger biscuits\nCocoa powder",
            Steps = "1. Whisk yolks and sugar until thick.\n2. Blend in mascarpone.\n3. Whip cream and fold into mixture.\n4. Dip ladyfingers in espresso.\n5. Layer biscuits and cream. Refrigerate 4 hours.\n6. Dust with cocoa before serving.",
            AverageRating = 4.7, RatingCount = 18
        },
        new Recipe
        {
            Id = 7, Title = "Caesar Salad", Category = "Lunch",
            Ingredients = "1 romaine lettuce\nCroutons\nParmesan cheese\nCaesar dressing\nLemon juice\nAnchovy paste",
            Steps = "1. Chop romaine lettuce.\n2. Toss with Caesar dressing.\n3. Add croutons and shaved Parmesan.\n4. Serve immediately.",
            AverageRating = 4.0, RatingCount = 10
        },
        new Recipe
        {
            Id = 8, Title = "Grilled Cheese Sandwich", Category = "Lunch",
            Ingredients = "2 slices bread\n2 slices cheddar cheese\n1 tbsp butter",
            Steps = "1. Butter the outside of each bread slice.\n2. Place cheese between slices.\n3. Grill on medium heat until golden and cheese is melted.\n4. Flip and cook the other side.",
            AverageRating = 4.1, RatingCount = 6
        }
    };

    public static List<string> Categories => Recipes.Select(r => r.Category).Distinct().ToList();

    public static List<Recipe> GetByCategory(string category) =>
        Recipes.Where(r => r.Category.Equals(category, StringComparison.OrdinalIgnoreCase)).ToList();

    public static Recipe? GetById(int id) => Recipes.FirstOrDefault(r => r.Id == id);
}

@rendermode InteractiveServer

<div class="star-rating">
    <span class="rating-label">Rate this recipe:</span>
    @for (int i = 1; i <= 5; i++)
    {
        var star = i;
        <span class="star @(star <= _currentRating ? "filled" : "")"
              @onclick="() => SetRating(star)"
              title="@star star(s)">
            @(star <= _currentRating ? "★" : "☆")
        </span>
    }
    @if (_submitted)
    {
        <span class="rating-feedback">Thanks! You rated @_currentRating star(s).</span>
    }
</div>

@code {
    [Parameter] public int RecipeId { get; set; }
    [Parameter] public double CurrentAverage { get; set; }
    [Parameter] public int RatingCount { get; set; }

    private int _currentRating;
    private bool _submitted;

    private void SetRating(int rating)
    {
        _currentRating = rating;
        _submitted = true;
    }
}

@page "/submit"
@rendermode InteractiveServer
@using RecipeCommunity.Models

<PageTitle>Submit a Recipe</PageTitle>

<h1>Submit a Recipe</h1>
<p class="text-muted">Share your favorite recipe with the community.</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Recipe Submitted!</h4>
        <p>Thank you for sharing "<strong>@_title</strong>" with the community.</p>
        <a href="/" class="btn btn-primary">Back to Home</a>
    </div>
}
else
{
    <EditForm Model="_model" OnValidSubmit="HandleSubmit" FormName="recipeForm">
        <DataAnnotationsValidator />
        <ValidationSummary class="text-danger" />

        <div class="mb-3">
            <label for="title" class="form-label">Recipe Title</label>
            <InputText id="title" class="form-control" @bind-Value="_model.Title" placeholder="e.g., Grandma's Apple Pie" />
            <ValidationMessage For="() => _model.Title" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="category" class="form-label">Category</label>
            <InputSelect id="category" class="form-select" @bind-Value="_model.Category">
                <option value="">-- Select a category --</option>
                <option value="Breakfast">Breakfast</option>
                <option value="Lunch">Lunch</option>
                <option value="Dinner">Dinner</option>
                <option value="Desserts">Desserts</option>
            </InputSelect>
            <ValidationMessage For="() => _model.Category" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="ingredients" class="form-label">Ingredients</label>
            <InputTextArea id="ingredients" class="form-control" rows="5" @bind-Value="_model.Ingredients" placeholder="One ingredient per line" />
            <ValidationMessage For="() => _model.Ingredients" class="text-danger" />
        </div>

        <div class="mb-3">
            <label for="steps" class="form-label">Steps</label>
            <InputTextArea id="steps" class="form-control" rows="5" @bind-Value="_model.Steps" placeholder="Describe each step" />
            <ValidationMessage For="() => _model.Steps" class="text-danger" />
        </div>

        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeFormModel _model = new();
    private bool _submitted;
    private string _title = string.Empty;

    private void HandleSubmit()
    {
        _title = _model.Title;
        _submitted = true;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required.")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Category is required.")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required.")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required.")]
        public string Steps { get; set; } = string.Empty;
    }
}

@page "/category/{CategoryName}"
@using RecipeCommunity.Models

<PageTitle>@CategoryName Recipes</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (_recipes.Any())
{
    <div class="row">
        @foreach (var recipe in _recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            ★ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <p>No recipes found in this category.</p>
}

<a href="/" class="btn btn-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private List<Recipe> _recipes = new();

    protected override void OnParametersSet()
    {
        _recipes = RecipeData.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Models
@using RecipeCommunity.Components.Shared

<PageTitle>@(_recipe?.Title ?? "Recipe Not Found")</PageTitle>

@if (_recipe is not null)
{
    <h1>@_recipe.Title</h1>
    <p class="text-muted">Category: <a href="/category/@_recipe.Category">@_recipe.Category</a></p>

    <div class="mb-3">
        <span class="badge bg-warning text-dark fs-6">
            ★ @_recipe.AverageRating.ToString("F1") (@_recipe.RatingCount ratings)
        </span>
    </div>

    <div class="card mb-4">
        <div class="card-header"><strong>Ingredients</strong></div>
        <div class="card-body">
            <ul class="mb-0">
                @foreach (var ingredient in _recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                {
                    <li>@ingredient</li>
                }
            </ul>
        </div>
    </div>

    <div class="card mb-4">
        <div class="card-header"><strong>Steps</strong></div>
        <div class="card-body">
            @foreach (var step in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <p class="mb-1">@step</p>
            }
        </div>
    </div>

    <div class="card mb-4">
        <div class="card-body">
            <StarRating RecipeId="@_recipe.Id"
                        CurrentAverage="@_recipe.AverageRating"
                        RatingCount="@_recipe.RatingCount" />
        </div>
    </div>

    <a href="/category/@_recipe.Category" class="btn btn-secondary">← Back to @_recipe.Category</a>
}
else
{
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
    <a href="/" class="btn btn-primary">Back to Home</a>
}

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeData.GetById(Id);
    }
}

