        <button type="submit" class="btn btn-success">Submit Recipe</button>
    </EditForm>
}

@code {
    private RecipeFormModel _model = new();
    private bool _submitted;
    private string _title = string.Empty;

    private void HandleSubmit()
    {
        _title = _model.Title;
        _submitted = true;
    }

    private class RecipeFormModel
    {
        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Title is required.")]
        public string Title { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Category is required.")]
        public string Category { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Ingredients are required.")]
        public string Ingredients { get; set; } = string.Empty;

        [System.ComponentModel.DataAnnotations.Required(ErrorMessage = "Steps are required.")]
        public string Steps { get; set; } = string.Empty;
    }
}

@page "/category/{CategoryName}"
@using RecipeCommunity.Models

<PageTitle>@CategoryName Recipes</PageTitle>

<h1>@CategoryName Recipes</h1>

@if (_recipes.Any())
{
    <div class="row">
        @foreach (var recipe in _recipes)
        {
            <div class="col-md-6 mb-4">
                <div class="card h-100">
                    <div class="card-body">
                        <h5 class="card-title">@recipe.Title</h5>
                        <p class="card-text text-muted">
                            ★ @recipe.AverageRating.ToString("F1") (@recipe.RatingCount ratings)
                        </p>
                        <a href="/recipe/@recipe.Id" class="btn btn-outline-primary">View Recipe</a>
                    </div>
                </div>
            </div>
        }
    </div>
}
else
{
    <p>No recipes found in this category.</p>
}

<a href="/" class="btn btn-secondary mt-3">← Back to Categories</a>

@code {
    [Parameter] public string CategoryName { get; set; } = string.Empty;

    private List<Recipe> _recipes = new();

    protected override void OnParametersSet()
    {
        _recipes = RecipeData.GetByCategory(CategoryName);
    }
}

@page "/recipe/{Id:int}"
@using RecipeCommunity.Models
@using RecipeCommunity.Components.Shared

<PageTitle>@(_recipe?.Title ?? "Recipe Not Found")</PageTitle>

@if (_recipe is not null)
{
    <h1>@_recipe.Title</h1>
    <p class="text-muted">Category: <a href="/category/@_recipe.Category">@_recipe.Category</a></p>

    <div class="mb-3">
        <span class="badge bg-warning text-dark fs-6">
            ★ @_recipe.AverageRating.ToString("F1") (@_recipe.RatingCount ratings)
        </span>
    </div>

    <div class="card mb-4">
        <div class="card-header"><strong>Ingredients</strong></div>
        <div class="card-body">
            <ul class="mb-0">
                @foreach (var ingredient in _recipe.Ingredients.Split('\n', StringSplitOptions.RemoveEmptyEntries))
                {
                    <li>@ingredient</li>
                }
            </ul>
        </div>
    </div>

    <div class="card mb-4">
        <div class="card-header"><strong>Steps</strong></div>
        <div class="card-body">
            @foreach (var step in _recipe.Steps.Split('\n', StringSplitOptions.RemoveEmptyEntries))
            {
                <p class="mb-1">@step</p>
            }
        </div>
    </div>

    <div class="card mb-4">
        <div class="card-body">
            <StarRating RecipeId="@_recipe.Id"
                        CurrentAverage="@_recipe.AverageRating"
                        RatingCount="@_recipe.RatingCount" />
        </div>
    </div>

    <a href="/category/@_recipe.Category" class="btn btn-secondary">← Back to @_recipe.Category</a>
}
else
{
    <h1>Recipe Not Found</h1>
    <p>The recipe you're looking for doesn't exist.</p>
    <a href="/" class="btn btn-primary">Back to Home</a>
}

@code {
    [Parameter] public int Id { get; set; }

    private Recipe? _recipe;

    protected override void OnParametersSet()
    {
        _recipe = RecipeData.GetById(Id);
    }
}

